actions.script:
const L = (text) => ec.l10n.localize(text)
const fmt = (value) => value == null ? '' : ec.l10n.format(Math.round(Number(String(value)) * 10) / 10, '#,##0.#')
const options = ec.service.sync().name('ironstone.projects.ReportServices.get#ReportOptions').call() || {}
ec.message.clearErrors()
managerOptions = Array.from(options.managerOptions || [])
clientOptions = Array.from(options.clientOptions || [])
programOptions = Array.from(options.programOptions || [])
statusOptions = [{value: '', label: L('Open (not closed or cancelled)')}, {value: 'all', label: L('All')}].concat(
    ['WeInPlanning', 'WeApproved', 'WeInProgress', 'WeOnHold', 'WeComplete', 'WeClosed', 'WeCancelled'].map((id) => ({value: id,
        label: ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id})))
const out = ec.service.sync().name('mantle.work.ProjectReportServices.get#PortfolioStatus').parameters({statusId: statusId || null,
    managerPartyId: managerPartyId || null, clientPartyId: clientPartyId || null, parentWorkEffortId: parentWorkEffortId || null}).call() || {}
ec.message.clearErrors()
moneyShown = !!out.moneyShown
const totals = out.totals || {}
const dayText = (day) => day ? ec.l10n.format(ec.l10n.parseTimestamp(day + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d, yyyy') : ''
const healthColors = {WehOnTrack: 'positive', WehAtRisk: 'warning', WehOffTrack: 'negative'}
const projects = Array.from(out.projectList || [])
portfolioRows = projects.map((row) => ({workEffortId: row.workEffortId, projectText: row.workEffortName + ' (' + row.workEffortId + ')',
    statusLabel: row.statusLabel || '', healthLabel: row.healthLabel || L('Not set'), healthColor: healthColors[row.healthEnumId] || 'grey-7',
    percentText: row.percentComplete == null ? '' : fmt(row.percentComplete) + '%', targetText: dayText(row.targetDate), forecastText: dayText(row.forecastDate),
    late: !!row.late, atRisk: !!row.atRisk, openCount: row.openCount || 0, overdueCount: row.overdueCount || 0,
    hoursText: [fmt(row.actualHours), row.estimatedHours != null ? fmt(row.estimatedHours) : ''].filter((part) => part !== '').join(' / '),
    budgetText: row.hoursBudget == null ? '' : fmt(row.hoursBudget), hoursUsedText: row.hoursUsedPercent == null ? '' : fmt(row.hoursUsedPercent) + '%',
    clientBudgetText: moneyShown && row.clientBudget != null ? ec.l10n.formatCurrency(row.clientBudget, row.currencyUomId || 'USD') : '',
    budgetUsedText: moneyShown && row.budgetUsedPercent != null ? fmt(row.budgetUsedPercent) + '%' : '',
    managerNames: row.managerNames || '', clientName: row.clientName || '', parentName: row.parentName || ''}))
portfolioRowsCount = portfolioRows.length
anyFound = portfolioRows.length > 0
projectsValue = String(totals.projectCount || 0)
atRiskValue = String(totals.atRiskCount || 0)
lateValue = String(totals.lateCount || 0)
overdueValue = String(totals.overdueCount || 0)
// the chart: % complete by project (projects with an estimate)
const charted = projects.filter((row) => row.percentComplete != null)
hasChart = charted.length > 0
const chart = hasChart ? ec.service.sync().name('ironstone.projects.ReportServices.get#ChartConfig').parameters({id: 'PortfolioChart', type: 'bar',
    labels: charted.map((row) => row.workEffortName), series: [{name: L('% complete'), data: charted.map((row) => row.percentComplete)}], horizontal: true,
    percent: true, height: Math.max(160, 40 + charted.length * 32) + 'px'}).call() || {} : {}
ec.message.clearErrors()
chartHtml = chart.html || ''
chartTui = chart.tui || {t: 'text', text: ''}
const query = {statusId: statusId || '', managerPartyId: managerPartyId || '', clientPartyId: clientPartyId || '', parentWorkEffortId: parentWorkEffortId || ''}
const params = Object.entries(query).filter(([key, value]) => value).map(([key, value]) => key + '=' + encodeURIComponent(value)).join('&')
printUrl = '/apps/Projects/Reports/Portfolio?renderMode=html-print' + (params ? '&' + params : '')
